def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))

    def runs(vals):
        out = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            color = vals[i]
            j = i + 1
            while j < len(vals) and vals[j] == color:
                j += 1
            out.append((color, i, j - 1))
            i = j
        return out

    # Find matching colored segments on opposite borders.
    candidates = []
    for orientation in ("horizontal", "vertical"):
        if orientation == "horizontal":
            a, b = runs(grid[0]), runs(grid[-1])
        else:
            a = runs([grid[r][0] for r in range(h)])
            b = runs([grid[r][-1] for r in range(h)])
        for ca, a0, a1 in a:
            for cb, b0, b1 in b:
                if ca == cb and a1 - a0 == b1 - b0:
                    candidates.append((orientation, ca, a0, a1, b0, b1))
    if not candidates:
        return [row[:] for row in grid]

    orientation, bar, a0, a1, b0, b1 = candidates[0]
    out = [row[:] for row in grid]
    axis_len = w if orientation == "horizontal" else h
    perp_len = h if orientation == "horizontal" else w
    seg_len = a1 - a0 + 1

    def get(p, k):
        return grid[p][k] if orientation == "horizontal" else grid[k][p]

    def setv(p, k, value):
        if orientation == "horizontal":
            out[p][k] = value
        else:
            out[k][p] = value

    # Locate marker cells lying within either border segment.
    markers = []
    for p in range(perp_len):
        for k in range(axis_len):
            val = get(p, k)
            if val == bg or val == bar:
                continue
            if a0 <= k <= a1:
                markers.append((p, k, val, 0, k - a0))
            elif b0 <= k <= b1:
                markers.append((p, k, val, 1, k - b0))

    for p, k, color, side, offset in markers:
        # Extend from the associated border to the marker; mark its endpoint.
        edge_p = 0 if side == 0 else perp_len - 1
        step = 1 if p > edge_p else -1
        q = edge_p + step
        while q != p:
            setv(q, k, color)
            q += step
        setv(p, k, 4)

        # At the corresponding position on the opposite border, extend a full ray.
        partner = (b0 + offset) if side == 0 else (a0 + offset)
        for q in range(perp_len):
            if get(q, partner) != bar:
                setv(q, partner, color)

    return out
